"""
Checkerboard Room V10 — Eevee/web-matched lighting + decorative glass chandelier
================================================================================

Creates one fully enclosed room whose visible design lives in Blender/GLB,
not in webpage runtime overrides:

- Smaller, highly polished dark-teal glazed subway tiles with crisp grout
- Green marble recolored to the exact wall-green hue while retaining its texture,
  normal map, roughness map, and natural light/dark marble variation
- The original soft-white marble checkerboard texture remains unchanged
- A decorative smoked-glass eight-arm chandelier with gently glowing glass bulbs
- No chandelier light objects and no chandelier-cast shadows
- Two hidden, shadowless warm spotlights exported in WEB_EXPORT for both Blender
  Eevee and the website to use as the same direct-light rig
- AgX color management with a documented matching Three.js exposure
- Organized WEB_EXPORT and RENDER_RIG collections

Tested for Python syntax outside Blender. Designed for Blender 3.6+ / 4.x / 5.x.
Run from Blender's Scripting workspace.
"""

import bpy
import math
import random
import base64
import os
import tempfile
from mathutils import Vector

# =========================================================
# USER SETTINGS
# =========================================================
SEED = 946

ROOM_WIDTH = 6.8
ROOM_DEPTH = 10.0
ROOM_HEIGHT = 3.6

# One authoritative green used by both the wall faces and the green marble tint.
WALL_GREEN_HEX = "#173936"

# Smaller long/low subway tiles. The proportions and running-bond style remain
# unchanged, but the denser grid reads closer to the supplied reference.
WALL_TILE_WIDTH = 0.240
WALL_TILE_HEIGHT = 0.090
WALL_GAP_X = 0.0045
WALL_GAP_Z = 0.0045
WALL_TILE_DEPTH = 0.024
WALL_TILE_BEVEL = 0.0036

FLOOR_TILE_SIZE = 0.285
# Zero gap keeps neighboring floor tiles edge-to-edge.
FLOOR_GAP = 0.000
FLOOR_TILE_DEPTH = 0.036

APPLY_WEB_MODIFIERS = True

RENDER_WIDTH = 1600
RENDER_HEIGHT = 1000
EEVEE_RENDER_SAMPLES = 64

# Blender exposure is expressed in stops. Three.js toneMappingExposure is a
# linear multiplier, so 2 ** stops is the matching website starting value.
EEVEE_EXPOSURE_STOPS = -0.65
WEB_TONE_MAPPING_EXPOSURE = 2.0 ** EEVEE_EXPOSURE_STOPS

random.seed(SEED)

# =========================================================
# CLEAN SCENE
# =========================================================
bpy.ops.object.select_all(action="SELECT")
bpy.ops.object.delete(use_global=False)

for datablocks in (
    bpy.data.meshes,
    bpy.data.curves,
    bpy.data.materials,
    bpy.data.cameras,
    bpy.data.lights,
):
    for block in list(datablocks):
        if block.users == 0:
            try:
                datablocks.remove(block)
            except RuntimeError:
                pass

# Remove prior generated texture datablocks while preserving Blender's built-in
# Render Result / Viewer images.
for image in list(bpy.data.images):
    if image.name.startswith((
        "White_Marble_Reference_",
        "Green_Marble_Reference_",
        "Reference_Exact_",
        "Ivory_Marble_Packed",
        "Green_Marble_Packed",
    )):
        try:
            bpy.data.images.remove(image)
        except RuntimeError:
            pass

# Make repeated script runs deterministic instead of accumulating .001
# collection names. Objects have already been deleted, so these are safe to remove.
for collection in list(bpy.data.collections):
    try:
        bpy.data.collections.remove(collection)
    except RuntimeError:
        pass

scene = bpy.context.scene
root_collection = scene.collection

web_collection = bpy.data.collections.new("WEB_EXPORT")
room_collection = bpy.data.collections.new("ROOM_ASSET")
chandelier_collection = bpy.data.collections.new("CHANDELIER_ASSET")
rig_collection = bpy.data.collections.new("RENDER_RIG")

root_collection.children.link(web_collection)
web_collection.children.link(room_collection)
web_collection.children.link(chandelier_collection)
root_collection.children.link(rig_collection)

# =========================================================
# RENDER SETUP — EEVEE, MATCHED TO THE WEBSITE
# =========================================================
selected_engine = None
for engine_name in (
    "BLENDER_EEVEE_NEXT",
    "BLENDER_EEVEE",
):
    try:
        scene.render.engine = engine_name
        selected_engine = engine_name
        break
    except (TypeError, ValueError):
        continue

if selected_engine is None:
    raise RuntimeError("Eevee is required but was not found in this Blender build.")

# Eevee property names vary between Blender generations. These guarded writes
# keep the script compatible while preferring a clean, stable real-time preview.
try:
    scene.eevee.taa_render_samples = EEVEE_RENDER_SAMPLES
except Exception:
    pass
try:
    scene.eevee.taa_samples = min(EEVEE_RENDER_SAMPLES, 32)
except Exception:
    pass
try:
    scene.eevee.use_gtao = True
    scene.eevee.gtao_distance = 3.0
    scene.eevee.gtao_factor = 0.65
except Exception:
    pass

scene.render.resolution_x = RENDER_WIDTH
scene.render.resolution_y = RENDER_HEIGHT
scene.render.resolution_percentage = 100
scene.render.image_settings.file_format = "PNG"
scene.render.film_transparent = False

for transform_name in ("AgX", "Filmic", "Standard"):
    try:
        scene.view_settings.view_transform = transform_name
        break
    except (TypeError, ValueError):
        continue

for look_name in (
    "AgX - Medium High Contrast",
    "Medium High Contrast",
    "Medium High Contrast Look",
    "None",
):
    try:
        scene.view_settings.look = look_name
        break
    except (TypeError, ValueError):
        continue

scene.view_settings.exposure = EEVEE_EXPOSURE_STOPS
try:
    scene.view_settings.gamma = 1.0
except Exception:
    pass

# =========================================================
# GENERAL HELPERS
# =========================================================
def get_socket(node, *names):
    for name in names:
        if name in node.inputs:
            return node.inputs[name]
    return None


def set_input(node, names, value):
    if isinstance(names, str):
        names = (names,)
    target = get_socket(node, *names)
    if target is not None:
        target.default_value = value


def srgb_hex(hex_color):
    """Convert a display-space hex color to Blender's linear RGBA values."""
    value = hex_color.strip().lstrip("#")
    if len(value) != 6:
        raise ValueError(f"Expected a six-digit hex color, got {hex_color!r}")

    channels = [int(value[index:index + 2], 16) / 255.0 for index in (0, 2, 4)]

    def to_linear(channel):
        if channel <= 0.04045:
            return channel / 12.92
        return ((channel + 0.055) / 1.055) ** 2.4

    return tuple(to_linear(channel) for channel in channels) + (1.0,)


def move_to_collection(obj, collection):
    for current in list(obj.users_collection):
        current.objects.unlink(obj)
    collection.objects.link(obj)


def aim_object(obj, target, track_axis="-Z", up_axis="Y"):
    direction = Vector(target) - obj.location
    obj.rotation_euler = direction.to_track_quat(track_axis, up_axis).to_euler()


def apply_modifier_safely(obj, modifier_name):
    if not APPLY_WEB_MODIFIERS:
        return
    try:
        bpy.ops.object.select_all(action="DESELECT")
        obj.select_set(True)
        bpy.context.view_layer.objects.active = obj
        bpy.ops.object.modifier_apply(modifier=modifier_name)
    except Exception as exc:
        print(f"Could not apply {modifier_name} on {obj.name}: {exc}")


def add_bevel_and_normals(obj, width, segments=3):
    bevel = obj.modifiers.new("Baked rounded edges", "BEVEL")
    bevel.width = width
    bevel.segments = segments
    bevel.limit_method = "ANGLE"
    if hasattr(bevel, "harden_normals"):
        bevel.harden_normals = True
    apply_modifier_safely(obj, bevel.name)

    try:
        weighted = obj.modifiers.new("Baked weighted normals", "WEIGHTED_NORMAL")
        weighted.keep_sharp = True
        apply_modifier_safely(obj, weighted.name)
    except Exception:
        pass


def add_cube(name, location, dimensions, material=None, collection=room_collection, bevel=0.0):
    bpy.ops.mesh.primitive_cube_add(size=1, location=location)
    obj = bpy.context.active_object
    obj.name = name
    obj.dimensions = dimensions
    bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)
    move_to_collection(obj, collection)
    if material is not None:
        obj.data.materials.append(material)
    if bevel > 0:
        add_bevel_and_normals(obj, bevel)
    return obj


def add_cylinder(
    name,
    location,
    radius,
    depth,
    material=None,
    collection=chandelier_collection,
    vertices=40,
    bevel=0.0,
):
    bpy.ops.mesh.primitive_cylinder_add(
        vertices=vertices,
        radius=radius,
        depth=depth,
        location=location,
    )
    obj = bpy.context.active_object
    obj.name = name
    move_to_collection(obj, collection)
    if material is not None:
        obj.data.materials.append(material)
    if bevel > 0:
        add_bevel_and_normals(obj, bevel)
    return obj


def add_uv_sphere(
    name,
    location,
    radius,
    material=None,
    collection=chandelier_collection,
    scale=(1.0, 1.0, 1.0),
):
    bpy.ops.mesh.primitive_uv_sphere_add(segments=40, ring_count=24, radius=radius, location=location)
    obj = bpy.context.active_object
    obj.name = name
    obj.scale = scale
    bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)
    move_to_collection(obj, collection)
    if material is not None:
        obj.data.materials.append(material)
    for polygon in obj.data.polygons:
        polygon.use_smooth = True
    return obj


def add_torus(
    name,
    location,
    major_radius,
    minor_radius,
    rotation=(0.0, 0.0, 0.0),
    material=None,
    collection=chandelier_collection,
):
    bpy.ops.mesh.primitive_torus_add(
        major_segments=32,
        minor_segments=10,
        major_radius=major_radius,
        minor_radius=minor_radius,
        location=location,
        rotation=rotation,
    )
    obj = bpy.context.active_object
    obj.name = name
    move_to_collection(obj, collection)
    if material is not None:
        obj.data.materials.append(material)
    for polygon in obj.data.polygons:
        polygon.use_smooth = True
    return obj


def add_bezier_tube(name, points, radius, material, collection=chandelier_collection):
    curve_data = bpy.data.curves.new(f"{name}_Curve", type="CURVE")
    curve_data.dimensions = "3D"
    curve_data.resolution_u = 20
    curve_data.render_resolution_u = 28
    curve_data.bevel_depth = radius
    curve_data.bevel_resolution = 5
    curve_data.resolution_u = 24

    spline = curve_data.splines.new("BEZIER")
    spline.bezier_points.add(len(points) - 1)
    for point, coordinate in zip(spline.bezier_points, points):
        point.co = coordinate
        point.handle_left_type = "AUTO"
        point.handle_right_type = "AUTO"

    obj = bpy.data.objects.new(name, curve_data)
    collection.objects.link(obj)
    obj.data.materials.append(material)

    # Convert to a real mesh so the GLB does not depend on curve support.
    bpy.ops.object.select_all(action="DESELECT")
    obj.select_set(True)
    bpy.context.view_layer.objects.active = obj
    bpy.ops.object.convert(target="MESH")
    converted = bpy.context.active_object
    converted.name = name
    for polygon in converted.data.polygons:
        polygon.use_smooth = True
    return converted

