def set_image_colorspace(image, preferred):
    candidates = (preferred, "Non-Color", "sRGB", "Linear")
    for candidate in candidates:
        try:
            image.colorspace_settings.name = candidate
            return
        except Exception:
            continue


def load_embedded_texture(image_name, encoded_png, colorspace):
    temp_root = bpy.app.tempdir or tempfile.gettempdir()
    os.makedirs(temp_root, exist_ok=True)
    file_path = os.path.join(temp_root, f"{image_name}_{SEED}.png")

    with open(file_path, "wb") as handle:
        handle.write(base64.b64decode(encoded_png))

    image = bpy.data.images.load(file_path, check_existing=False)
    image.name = image_name
    image.file_format = "PNG"
    set_image_colorspace(image, colorspace)
    try:
        image.pack()
    except Exception as exc:
        print(f"Could not pack {image_name}: {exc}")
    return image


floor_texture_sets = {}
for stone_name, maps in EMBEDDED_FLOOR_TEXTURES.items():
    floor_texture_sets[stone_name] = {
        "color": load_embedded_texture(
            f"Reference_Exact_{stone_name}_Color",
            maps["color"],
            "sRGB",
        ),
        "normal": load_embedded_texture(
            f"Reference_Exact_{stone_name}_Normal",
            maps["normal"],
            "Non-Color",
        ),
        "roughness": load_embedded_texture(
            f"Reference_Exact_{stone_name}_Roughness",
            maps["roughness"],
            "Non-Color",
        ),
    }


def create_wall_matched_marble_image(source_image, image_name, target_color):
    """Recolor marble to the wall hue while preserving its original luminance."""
    width, height = source_image.size
    source_pixels = list(source_image.pixels[:])
    pixel_count = max(1, width * height)

    luminance_sum = 0.0
    for index in range(0, len(source_pixels), 4):
        red, green, blue = source_pixels[index:index + 3]
        luminance_sum += red * 0.2126 + green * 0.7152 + blue * 0.0722
    average_luminance = max(luminance_sum / pixel_count, 1e-5)

    target_red, target_green, target_blue = target_color[:3]
    result = [0.0] * len(source_pixels)
    for index in range(0, len(source_pixels), 4):
        red, green, blue, alpha = source_pixels[index:index + 4]
        luminance = red * 0.2126 + green * 0.7152 + blue * 0.0722
        relative_value = max(0.28, min(2.60, luminance / average_luminance))

        if relative_value <= 1.0:
            out_red = target_red * relative_value
            out_green = target_green * relative_value
            out_blue = target_blue * relative_value
        else:
            highlight = min(1.0, (relative_value - 1.0) * 0.62)
            out_red = target_red + (1.0 - target_red) * highlight
            out_green = target_green + (1.0 - target_green) * highlight
            out_blue = target_blue + (1.0 - target_blue) * highlight

        result[index] = max(0.0, min(1.0, out_red))
        result[index + 1] = max(0.0, min(1.0, out_green))
        result[index + 2] = max(0.0, min(1.0, out_blue))
        result[index + 3] = alpha

    image = bpy.data.images.new(image_name, width=width, height=height, alpha=True)
    image.file_format = "PNG"
    set_image_colorspace(image, "sRGB")
    image.pixels.foreach_set(result)
    image.update()
    try:
        image.pack()
    except Exception as exc:
        print(f"Could not pack {image_name}: {exc}")
    return image


# Replace only the green color maps. Normal and roughness maps, UVs, and the
# original white marble remain untouched. Baking the tint into the image also
# guarantees that standard glTF/GLB exporters carry the match to the website.
wall_green_for_textures = srgb_hex(WALL_GREEN_HEX)
for green_name in ("Green_Marble_Exact_A", "Green_Marble_Exact_B"):
    original_color = floor_texture_sets[green_name]["color"]
    floor_texture_sets[green_name]["color"] = create_wall_matched_marble_image(
        original_color,
        f"Reference_Wall_Matched_{green_name}_Color",
        wall_green_for_textures,
    )

