def make_principled_material(
    name,
    base_color,
    roughness,
    metallic=0.0,
    coat=0.0,
    emission=None,
    emission_strength=0.0,
    transmission=0.0,
):
    material = bpy.data.materials.new(name)
    material.use_nodes = True
    nodes = material.node_tree.nodes
    links = material.node_tree.links
    nodes.clear()

    output = nodes.new("ShaderNodeOutputMaterial")
    output.location = (420, 0)
    bsdf = nodes.new("ShaderNodeBsdfPrincipled")
    bsdf.location = (80, 0)

    set_input(bsdf, "Base Color", base_color)
    set_input(bsdf, "Roughness", roughness)
    set_input(bsdf, "Metallic", metallic)
    set_input(bsdf, ("Coat Weight", "Clearcoat"), coat)
    set_input(bsdf, ("Coat Roughness", "Clearcoat Roughness"), 0.045)
    set_input(bsdf, "IOR", 1.47)
    set_input(bsdf, ("Transmission Weight", "Transmission"), transmission)

    if emission is not None:
        set_input(bsdf, ("Emission Color", "Emission"), emission)
        set_input(bsdf, "Emission Strength", emission_strength)

    links.new(bsdf.outputs["BSDF"], output.inputs["Surface"])
    return material, bsdf, nodes, links


def make_reference_marble_material(
    name,
    texture_set,
    coat=0.20,
    normal_strength=0.22,
):
    material, bsdf, nodes, links = make_principled_material(
        name,
        (1.0, 1.0, 1.0, 1.0),
        roughness=0.22,
        coat=coat,
    )

    color_texture = nodes.new("ShaderNodeTexImage")
    color_texture.name = f"{name}_BaseColor"
    color_texture.image = texture_set["color"]
    color_texture.interpolation = "Linear"
    color_texture.extension = "EXTEND"
    color_texture.location = (-620, 140)
    links.new(color_texture.outputs["Color"], get_socket(bsdf, "Base Color"))

    roughness_texture = nodes.new("ShaderNodeTexImage")
    roughness_texture.name = f"{name}_Roughness"
    roughness_texture.image = texture_set["roughness"]
    roughness_texture.interpolation = "Linear"
    roughness_texture.extension = "EXTEND"
    roughness_texture.location = (-620, -70)
    links.new(roughness_texture.outputs["Color"], get_socket(bsdf, "Roughness"))

    normal_texture = nodes.new("ShaderNodeTexImage")
    normal_texture.name = f"{name}_Normal"
    normal_texture.image = texture_set["normal"]
    normal_texture.interpolation = "Linear"
    normal_texture.extension = "EXTEND"
    normal_texture.location = (-620, -290)

    normal_map = nodes.new("ShaderNodeNormalMap")
    normal_map.name = f"{name}_NormalMap"
    normal_map.location = (-280, -250)
    normal_map.inputs["Strength"].default_value = normal_strength
    links.new(normal_texture.outputs["Color"], normal_map.inputs["Color"])
    links.new(normal_map.outputs["Normal"], get_socket(bsdf, "Normal"))

    return material


