# =========================================================
# UV-CAPABLE MESH BUILDER
# =========================================================
class MeshBuilder:
    def __init__(self):
        self.vertices = []
        self.faces = []
        self.material_indices = []
        self.face_uvs = []

    @staticmethod
    def transformed_uvs(rotation_quarters=0, offset=(0.0, 0.0), scale=1.0):
        base = ((0.0, 0.0), (1.0, 0.0), (1.0, 1.0), (0.0, 1.0))
        result = []
        angle = rotation_quarters * math.pi / 2.0
        cos_a = math.cos(angle)
        sin_a = math.sin(angle)
        for u, v in base:
            x = (u - 0.5) * scale
            y = (v - 0.5) * scale
            rotated_u = x * cos_a - y * sin_a + 0.5 + offset[0]
            rotated_v = x * sin_a + y * cos_a + 0.5 + offset[1]
            result.append((rotated_u, rotated_v))
        return tuple(result)

    def add_box(
        self,
        center,
        dimensions,
        material_index=0,
        uv_rotation=0,
        uv_offset=(0.0, 0.0),
        uv_scale=1.0,
    ):
        cx, cy, cz = center
        hx, hy, hz = dimensions[0] / 2.0, dimensions[1] / 2.0, dimensions[2] / 2.0
        start = len(self.vertices)
        self.vertices.extend(
            (
                (cx - hx, cy - hy, cz - hz),
                (cx + hx, cy - hy, cz - hz),
                (cx + hx, cy + hy, cz - hz),
                (cx - hx, cy + hy, cz - hz),
                (cx - hx, cy - hy, cz + hz),
                (cx + hx, cy - hy, cz + hz),
                (cx + hx, cy + hy, cz + hz),
                (cx - hx, cy + hy, cz + hz),
            )
        )

        box_faces = (
            (0, 3, 2, 1),  # bottom
            (4, 5, 6, 7),  # top
            (0, 1, 5, 4),  # y-
            (1, 2, 6, 5),  # x+
            (2, 3, 7, 6),  # y+
            (3, 0, 4, 7),  # x-
        )
        uv_quad = self.transformed_uvs(uv_rotation, uv_offset, uv_scale)
        for face in box_faces:
            self.faces.append(tuple(start + index for index in face))
            self.material_indices.append(material_index)
            self.face_uvs.append(uv_quad)

    def finish(self, name, materials, collection, bevel_width=0.0):
        mesh = bpy.data.meshes.new(f"{name}_Mesh")
        mesh.from_pydata(self.vertices, [], self.faces)
        mesh.validate()
        mesh.update()

        for polygon, material_index in zip(mesh.polygons, self.material_indices):
            polygon.material_index = material_index

        uv_layer = mesh.uv_layers.new(name="UVMap")
        for polygon, uv_quad in zip(mesh.polygons, self.face_uvs):
            for loop_index, uv in zip(polygon.loop_indices, uv_quad):
                uv_layer.data[loop_index].uv = uv

        obj = bpy.data.objects.new(name, mesh)
        collection.objects.link(obj)
        for material in materials:
            obj.data.materials.append(material)

        if bevel_width > 0:
            add_bevel_and_normals(obj, bevel_width)
        return obj


def clipped_segments(total_length, nominal_length, gap, offset=0.0):
    """Return clipped tile spans with exactly one `gap` between neighbors."""
    lower = -total_length / 2.0
    upper = total_length / 2.0
    module = nominal_length + gap
    cursor = lower - module + offset
    segments = []
    while cursor < upper + module:
        segment_lower = max(lower, cursor)
        segment_upper = min(upper, cursor + nominal_length)
        if segment_upper - segment_lower > 0.055:
            segments.append(((segment_lower + segment_upper) / 2.0, segment_upper - segment_lower))
        cursor += module
    return segments

