# REFERENCE DARK-TEAL GLAZED SUBWAY WALL TILES
# =========================================================
def build_width_wall(name, y_position, inward_sign):
    builder = MeshBuilder()
    row_module = WALL_TILE_HEIGHT + WALL_GAP_Z
    row_count = math.ceil(ROOM_HEIGHT / row_module) + 1

    for row in range(row_count):
        z_lower = row * row_module + WALL_GAP_Z / 2.0
        z_upper = min(ROOM_HEIGHT, z_lower + WALL_TILE_HEIGHT)
        if z_upper - z_lower < 0.045:
            continue
        z_center = (z_lower + z_upper) / 2.0
        tile_height = z_upper - z_lower
        stagger = 0.0 if row % 2 == 0 else (WALL_TILE_WIDTH + WALL_GAP_X) / 2.0

        for x_center, tile_width in clipped_segments(
            ROOM_WIDTH,
            WALL_TILE_WIDTH,
            WALL_GAP_X,
            stagger,
        ):
            material_index = random.choices(range(4), weights=(4, 7, 4, 2))[0]
            builder.add_box(
                center=(
                    x_center,
                    y_position + inward_sign * WALL_TILE_DEPTH / 2.0,
                    z_center,
                ),
                dimensions=(tile_width, WALL_TILE_DEPTH, tile_height),
                material_index=material_index,
                uv_rotation=random.randrange(4),
                uv_offset=(random.random(), random.random()),
                uv_scale=0.85 + random.random() * 0.35,
            )

    return builder.finish(name, wall_materials, room_collection, bevel_width=WALL_TILE_BEVEL)


def build_side_wall(name, x_position):
    builder = MeshBuilder()
    row_module = WALL_TILE_HEIGHT + WALL_GAP_Z
    row_count = math.ceil(ROOM_HEIGHT / row_module) + 1

    for row in range(row_count):
        z_lower = row * row_module + WALL_GAP_Z / 2.0
        z_upper = min(ROOM_HEIGHT, z_lower + WALL_TILE_HEIGHT)
        if z_upper - z_lower < 0.045:
            continue
        z_center = (z_lower + z_upper) / 2.0
        tile_height = z_upper - z_lower
        stagger = 0.0 if row % 2 == 0 else (WALL_TILE_WIDTH + WALL_GAP_X) / 2.0

        for y_center, tile_width in clipped_segments(
            ROOM_DEPTH,
            WALL_TILE_WIDTH,
            WALL_GAP_X,
            stagger,
        ):
            inward = WALL_TILE_DEPTH / 2.0 if x_position < 0 else -WALL_TILE_DEPTH / 2.0
            material_index = random.choices(range(4), weights=(4, 7, 4, 2))[0]
            builder.add_box(
                center=(x_position + inward, y_center, z_center),
                dimensions=(WALL_TILE_DEPTH, tile_width, tile_height),
                material_index=material_index,
                uv_rotation=random.randrange(4),
                uv_offset=(random.random(), random.random()),
                uv_scale=0.85 + random.random() * 0.35,
            )

    return builder.finish(name, wall_materials, room_collection, bevel_width=WALL_TILE_BEVEL)


build_width_wall("Back_Wall_Glazed_Bricks", ROOM_DEPTH / 2.0, -1.0)
build_width_wall("Front_Wall_Glazed_Bricks", -ROOM_DEPTH / 2.0, 1.0)
build_side_wall("Left_Wall_Glazed_Bricks", -ROOM_WIDTH / 2.0)
build_side_wall("Right_Wall_Glazed_Bricks", ROOM_WIDTH / 2.0)

# =========================================================
# SMALL POLISHED MARBLE CHECKERBOARD FLOOR
# =========================================================
floor_builder = MeshBuilder()
x_segments = clipped_segments(ROOM_WIDTH, FLOOR_TILE_SIZE, FLOOR_GAP)
y_segments = clipped_segments(ROOM_DEPTH, FLOOR_TILE_SIZE, FLOOR_GAP)

for x_index, (x_center, tile_width) in enumerate(x_segments):
    for y_index, (y_center, tile_depth) in enumerate(y_segments):
        is_green = (x_index + y_index) % 2 == 0
        variant = random.randrange(2)
        material_index = variant if is_green else 2 + variant
        floor_builder.add_box(
            center=(x_center, y_center, FLOOR_TILE_DEPTH / 2.0),
            dimensions=(tile_width, tile_depth, FLOOR_TILE_DEPTH),
            material_index=material_index,
            # Rotate the complete stone sample instead of cropping or repeating it.
            uv_rotation=random.randrange(4),
            uv_offset=(0.0, 0.0),
            uv_scale=1.0,
        )

floor_builder.finish(
    "Edge_to_Edge_Green_White_Marble_Checkerboard_Floor",
    floor_materials,
    room_collection,
    # A microscopic bevel catches light at the seam without opening a grout gap.
    bevel_width=0.0008,
)

# =========================================================
# DECORATIVE SMOKED-GLASS EIGHT-ARM CHANDELIER
# Geometry and emissive glass only: it contains no Blender/glTF light objects.
# =========================================================
chandelier_root = bpy.data.objects.new("Warm_Chandelier_Root", None)
chandelier_collection.objects.link(chandelier_root)


def parent_to_chandelier(obj):
    obj.parent = chandelier_root
    return obj


# Ceiling medallion and layered brass canopy.
medallion = add_cylinder(
    "Chandelier_Ceiling_Medallion",
    (0, 0, ROOM_HEIGHT - 0.010),
    radius=0.42,
    depth=0.035,
    material=ceiling_material,
    bevel=0.012,
)
parent_to_chandelier(medallion)

canopy_lower = add_cylinder(
    "Chandelier_Brass_Canopy_Lower",
    (0, 0, ROOM_HEIGHT - 0.070),
    radius=0.28,
    depth=0.075,
    material=brass_material,
    bevel=0.015,
)
parent_to_chandelier(canopy_lower)

canopy_upper = add_cylinder(
    "Chandelier_Brass_Canopy_Upper",
    (0, 0, ROOM_HEIGHT - 0.118),
    radius=0.17,
    depth=0.055,
    material=dark_brass_material,
    bevel=0.012,
)
parent_to_chandelier(canopy_upper)

# Alternating chain links.
chain_top = ROOM_HEIGHT - 0.155
chain_bottom = 2.73
chain_count = 8
for index in range(chain_count):
    t = index / max(1, chain_count - 1)
    z = chain_top * (1.0 - t) + chain_bottom * t
    rotation = (math.pi / 2.0, 0.0, 0.0) if index % 2 == 0 else (math.pi / 2.0, 0.0, math.pi / 2.0)
    link = add_torus(
        f"Chandelier_Chain_Link_{index + 1}",
        (0, 0, z),
        major_radius=0.070,
        minor_radius=0.014,
        rotation=rotation,
        material=dark_brass_material,
    )
    link.scale = (0.72, 1.0, 1.38)
    bpy.ops.object.select_all(action="DESELECT")
    link.select_set(True)
    bpy.context.view_layer.objects.active = link
    bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)
    parent_to_chandelier(link)

# Central body.
stem = add_cylinder(
    "Chandelier_Central_Stem",
    (0, 0, 2.53),
    radius=0.055,
    depth=0.42,
    material=dark_brass_material,
    bevel=0.010,
)
parent_to_chandelier(stem)

upper_hub = add_uv_sphere(
    "Chandelier_Upper_Hub",
    (0, 0, 2.70),
    radius=0.16,
    material=brass_material,
    scale=(1.0, 1.0, 0.78),
)
parent_to_chandelier(upper_hub)

main_hub = add_uv_sphere(
    "Chandelier_Main_Hub",
    (0, 0, 2.38),
    radius=0.22,
    material=brass_material,
    scale=(1.0, 1.0, 0.82),
)
parent_to_chandelier(main_hub)

lower_drop = add_bezier_tube(
    "Chandelier_Lower_Drop",
    ((0, 0, 2.40), (0, 0, 2.25), (0, 0, 2.10)),
    radius=0.045,
    material=dark_brass_material,
)
parent_to_chandelier(lower_drop)

finial = add_uv_sphere(
    "Chandelier_Final_Finial",
    (0, 0, 2.06),
    radius=0.105,
    material=brass_material,
    scale=(0.72, 0.72, 1.30),
)
parent_to_chandelier(finial)

arm_count = 8
arm_radius = 1.05
bulb_height = 2.58

for index in range(arm_count):
    angle = index * math.tau / arm_count
    direction = Vector((math.cos(angle), math.sin(angle), 0.0))
    tangent = Vector((-math.sin(angle), math.cos(angle), 0.0))

    p0 = Vector((0, 0, 2.41))
    p1 = direction * 0.34 + Vector((0, 0, 2.28)) + tangent * 0.025
    p2 = direction * 0.74 + Vector((0, 0, 2.31)) - tangent * 0.025
    p3 = direction * arm_radius + Vector((0, 0, 2.47))

    arm = add_bezier_tube(
        f"Chandelier_Curved_Arm_{index + 1}",
        (tuple(p0), tuple(p1), tuple(p2), tuple(p3)),
        radius=0.031,
        material=brass_material,
    )
    parent_to_chandelier(arm)

    cup = add_cylinder(
        f"Chandelier_Candle_Cup_{index + 1}",
        (p3.x, p3.y, 2.49),
        radius=0.125,
        depth=0.035,
        material=brass_material,
        bevel=0.009,
    )
    parent_to_chandelier(cup)

    cup_ring = add_torus(
        f"Chandelier_Cup_Ring_{index + 1}",
        (p3.x, p3.y, 2.505),
        major_radius=0.092,
        minor_radius=0.012,
        material=dark_brass_material,
    )
    parent_to_chandelier(cup_ring)

    sleeve = add_cylinder(
        f"Chandelier_Candle_Sleeve_{index + 1}",
        (p3.x, p3.y, 2.605),
        radius=0.043,
        depth=0.205,
        material=candle_material,
        vertices=32,
        bevel=0.006,
    )
    parent_to_chandelier(sleeve)

    bulb = add_uv_sphere(
        f"Chandelier_Warm_Bulb_{index + 1}",
        (p3.x, p3.y, bulb_height + 0.15),
        radius=0.082,
        material=bulb_material,
        scale=(0.80, 0.80, 1.45),
    )
    parent_to_chandelier(bulb)

    bulb_tip = add_uv_sphere(
        f"Chandelier_Bulb_Tip_{index + 1}",
        (p3.x, p3.y, bulb_height + 0.245),
        radius=0.030,
        material=bulb_material,
        scale=(0.62, 0.62, 1.35),
    )
    parent_to_chandelier(bulb_tip)

    # Small crystal drop below every other arm.
    if index % 2 == 0:
        crystal_top = add_torus(
            f"Chandelier_Crystal_Ring_{index + 1}",
            (p2.x, p2.y, 2.23),
            major_radius=0.028,
            minor_radius=0.007,
            rotation=(math.pi / 2.0, 0.0, angle),
            material=brass_material,
        )
        parent_to_chandelier(crystal_top)

        crystal = add_uv_sphere(
            f"Chandelier_Crystal_Drop_{index + 1}",
            (p2.x, p2.y, 2.13),
            radius=0.060,
            material=crystal_material,
            scale=(0.62, 0.62, 1.45),
        )
        parent_to_chandelier(crystal)

# =========================================================
# SHARED BLENDER / WEBSITE LIGHT RIG
# =========================================================
def add_web_spotlight(
    name,
    location,
    target,
    energy,
    color_hex,
    spot_degrees,
    blend,
):
    light_data = bpy.data.lights.new(name, type="SPOT")
    light_data.energy = energy
    light_data.color = srgb_hex(color_hex)[:3]
    light_data.spot_size = math.radians(spot_degrees)
    light_data.spot_blend = blend
    light_data.shadow_soft_size = 0.55
    if hasattr(light_data, "use_shadow"):
        light_data.use_shadow = False
    if hasattr(light_data, "use_custom_distance"):
        light_data.use_custom_distance = True
        light_data.cutoff_distance = 14.0

    light_obj = bpy.data.objects.new(name, light_data)
    web_collection.objects.link(light_obj)
    light_obj.location = location
    aim_object(light_obj, target)
    return light_obj


# These are hidden above the viewer and export through KHR_lights_punctual.
# The website uses these imported lights directly instead of rebuilding a
# separate lighting rig, which keeps hue, placement, and intensity consistent.
add_web_spotlight(
    "Web_Key_Spot",
    (0.0, -0.55, ROOM_HEIGHT - 0.16),
    (0.15, 2.35, 0.75),
    energy=455.0,
    color_hex="#FFD6B2",
    spot_degrees=116.0,
    blend=0.88,
)
add_web_spotlight(
    "Web_Fill_Spot",
    (-1.85, -2.35, ROOM_HEIGHT - 0.34),
    (0.55, 3.95, 1.15),
    energy=165.0,
    color_hex="#F3DFCE",
    spot_degrees=104.0,
    blend=0.92,
)

