# CENTERED INSIDE-ROOM CAMERA / RENDER RIG
# =========================================================
camera_data = bpy.data.cameras.new("Interior_Look_Camera")
camera = bpy.data.objects.new("Interior_Look_Camera", camera_data)
rig_collection.objects.link(camera)
scene.camera = camera
camera.location = (0.0, 0.35, 1.62)
camera.data.lens = 20.0
camera.data.sensor_width = 36.0
camera.data.dof.use_dof = False
aim_object(camera, (1.55, ROOM_DEPTH / 2.0 - 0.45, 1.58))

# The camera collection intentionally contains no extra illumination. Blender
# and the website both use only Web_Key_Spot and Web_Fill_Spot from WEB_EXPORT.

# =========================================================
# WORLD / PACKING / FINAL STATE
# =========================================================
world = bpy.data.worlds.get("World") or bpy.data.worlds.new("World")
scene.world = world
world.use_nodes = True
background = world.node_tree.nodes.get("Background")
if background is not None:
    background.inputs["Color"].default_value = srgb_hex("#050403")
    background.inputs["Strength"].default_value = 0.004

# Ensure generated marble images remain inside the .blend.
try:
    bpy.ops.file.pack_all()
except Exception as exc:
    print(f"Packing warning: {exc}")

bpy.ops.object.select_all(action="DESELECT")
camera.select_set(True)
bpy.context.view_layer.objects.active = camera

